    return yield* Schema.decodeUnknownEffect(CodexOAuthRefreshPolicy)({
      refreshSkewMillis,
      lockTtlMillis,
    });
  }
).pipe(Effect.withSpan("CodexOAuthRefreshPolicy.load"));

