              {
                headers: { "content-type": "text/event-stream" },
                status: 200,
              }
            )
          ),
      })
    );
    const webHandler = makeCodexProxyWebHandler(
      makeCodexProxyAppLayer(
        CodexProxyConfigLayer(config),
        CodexProxyOpenAICompatibleProxyLiveOrUnavailable,
        () => localProxyLayer
      )
    );

