          )
        );

        return CodexOAuthHttpClientLive.pipe(
          Layer.provideMerge(
            Layer.merge(
              Layer.succeed(HttpClient.HttpClient, client),
              CodexSubscriptionAuthProtocolConfigLive
            )
          )
        );
